#!/usr/bin/env python3
"""Build a static, evidence-driven site. This never trains or authorizes a slot."""
from __future__ import annotations
import csv
import hashlib
import html
import io
import json
import shutil
import sys
from datetime import datetime,timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
DOCS=ROOT/'docs'
REPO='https://github.com/kanlerxz87-cyber/KANLERGEMSDOE3'

def read(p):return json.loads((ROOT/p).read_text())
def e(x):return html.escape(str(x),quote=True)
def f(x):return f'{x:.5f}'
def pct(x):return f'{100*x:.2f}%'
def tag(text,kind=''):return f'<span class="tag {kind}">{e(text)}</span>'

def page(title,body,active='Overview',prefix=''):
    nav=[('Overview','index.html'),('Executive summary','executive-summary.html'),('Research','research.html'),('Sources','sources.html'),('Audit','audit.html')]
    links=''.join(f'<a class="{"active" if name==active else ""}" href="{prefix}{url}"'+(' aria-current="page"'if name==active else '')+f'>{name}</a>'for name,url in nav)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Evidence-first DOE GEMS fault-discovery research. New GeoTIFF downloads, spatial holdout results, nine-site comparison and automated submission gates."><meta name="theme-color" content="#152c35"><title>{e(title)} · KANLER GEMS</title><link rel="stylesheet" href="{prefix}assets/site.css"><script defer src="{prefix}assets/site.js"></script></head>
<body><a class="skip" href="#main-content">Skip to content</a><header class="header"><nav class="nav" aria-label="Main navigation"><a class="brand" href="{prefix}index.html"><span class="brand-mark" aria-hidden="true">KG</span><span>KANLER GEMS<small>Fault discovery, with evidence</small></span></a><div class="nav-links">{links}</div></nav></header><main id="main-content">{body}</main><footer class="footer"><p><strong>Maximize P(Win).</strong> Measure what matters. Publish what happened.<br>Local validation is not an organizer score receipt.</p><p>Audit date: 26 Oct 2026 · <a href="{prefix}submission-guide.html">Submission guide</a> · <a href="{REPO}">Repository</a><br><a href="{prefix}data/run_card.json">One JSON run card</a> · No competition slot used.</p></footer></body></html>'''


def banner(c):
    ok=c['decision']['ok_to_submit']
    if ok:
        return '<div class="status-bar"><strong>Local promotion gates passed.</strong> Weekly-slot selection remains a separate operation.</div>'
    return '<div class="status-bar" role="status"><span class="status-icon" aria-hidden="true">●</span><div><strong>NO AUTHORIZED SUBMISSION — do not upload this run’s file.</strong><p>The new TIFF is downloadable and locally format-valid, but the automatic scientific / uniqueness gates reject it. No human inspection is needed to determine this status.</p></div></div>'


def download_panel(c,prefix=''):
    d=c['downloads'];v=c['validator_output']
    return f'''<aside class="download-card" aria-label="New GeoTIFF download and submission status"><p class="eyebrow">Newly generated · SSP1–E1</p><h2>A real file.<br>An honest verdict.</h2>{tag('Rejected · do not submit','red')}<p class="subtle" style="margin-top:15px">Not copied from a peer. Exact pixels are new within the comparable snapshot. Lane uniqueness still fails.</p><a class="button primary" href="{prefix}downloads/{e(d['tif'])}" download>↓ Download new TIF <span class="tiny" style="color:inherit">{v['size_bytes']/1000:.0f} KB</span></a><div class="button-row"><a class="button secondary small" href="{prefix}downloads/{e(d['zip'])}" download>Single-TIFF ZIP</a><a class="button secondary small" href="{prefix}data/run_card.json">Validation + run card</a></div><p class="tiny" style="margin-top:15px">DOWNLOAD: YES · SHARED FORMAT CHECKS: PASS<br>SUBMIT TO DRIVENDATA: NO · WEEKLY SLOTS USED: 0</p><details class="hash-box"><summary>Exact filename and SHA-256</summary><code>{e(d['tif'])}</code><code>{e(c['raster_sha256'])}</code></details></aside>'''


def estimate(c):
    h=c['holdout_dti'];lo,hi=h['ci95_cluster_bootstrap']
    return f'''<div class="stat-grid"><article class="stat"><div class="label">Local HOLDOUT-DTI · not leaderboard</div><div class="value">{f(h['pooled_dti'])}</div><p>95% spatial CI [{f(lo)}, {f(hi)}]<br>{e(h['evaluator_version'])}<br>{h['n_withheld_positives']:,} withheld positive-pixel events</p></article><article class="stat"><div class="label">Registered files · frozen snapshot</div><div class="value">{c['registry']['universe_files']:,} <span style="font-size:15px;letter-spacing:0">/ {c['registry']['universe_sites']} sites</span></div><p>{c['registry']['surface']['n_compared_files']:,} comparable; {c['registry']['surface']['n_quarantined']} explicitly quarantined.<br>0 exact candidate-mask matches in the comparable entries. Unpublished/later files are outside scope.</p></article><article class="stat"><div class="label">Final dot overlap · duplicate threshold 70%</div><div class="value fail">{pct(c['registry']['final_dots']['checks'][0]['fraction_candidate_dots_within_3px'])}</div><p>Within 3 px of the registered calibration lattice.<br>Stop at first duplicate. No re-placement, extra model trials, or submission slot.</p></article></div>'''


def peer_table(peers,prefix=''):
    rows=[]
    for r in peers['sites']:
        twins=', '.join(r['exact_mask_twins']) or 'No exact twin among these nine best-claim files'
        exact='NO' if r['exact_mask_twins'] else 'YES, among these nine only'
        lane='NO' if not r['lane_distinct_from_all_other_priority_sites'] else 'YES, among these nine'
        rows.append(f'''<tr class="{'champion'if r['site']=='GEMSDOE32'else ''}"><td class="site"><a href="{prefix}sites/{r['site']}.html">{r['site']}</a>{'<span class="note">Highest historical claim</span>'if r['site']=='GEMSDOE32'else ''}</td><td class="artifact"><a href="{e(r['download_url'])}">↓ Reference TIFF only</a><span class="filename">{e(r['filename'])}</span><span class="note">{r['dots']:,} dots · SHA {r['sha256'][:12]}…</span></td><td class="measure"><span class="score">{r['historical_claim']['value']:.4f}</span><span class="note">USER-REPORTED<br>NOT ORGANIZER-CONFIRMED<br>No hash-linked receipt</span></td><td>Unavailable<span class="note">Not inferred from a historical claim or a biased stored-mask diagnostic.</span></td><td><strong>{exact}</strong><span class="note">{e(twins)}</span></td><td><strong class="fail">{lane}</strong><span class="note">{pct(r['max_directional_overlap'])} within 3 px of {r['nearest_priority_site']}.</span></td><td><strong class="fail">NO</strong><span class="note">Already used / reproduced; not a new authorized candidate.</span></td></tr>''')
    return '<div class="table-shell"><table class="wide"><caption class="screen-reader">Nine-site best historical claim, pinned download, estimate availability and duplicate status</caption><thead><tr><th>Site</th><th>File to download · reference only</th><th>Historical claim</th><th>Estimated leaderboard result</th><th>Exact dot-mask unique?</th><th>Protocol-lane unique?</th><th>Submit now?</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'


def gates(c):
    labels={
      'declared_lane':('One declared method lane','SSP1, declared autonomously; no external assignment was provided.'),
      'leakage_canaries':('Every feature alone · leakage canary','17 features; maximum either-direction AUC '+f"{c['leakage_canary']['max_either_direction_auc']:.4f}"+' ≤ 0.90. AUC is a diagnostic, not a score.'),
      'surface_unique':('Pre-placement surface correlation','Fixed-array recheck max |Spearman| '+f"{c['registry']['surface']['max_abs_spearman']:.4f}"+'; original correlation log was not exactly reproduced. 18 incompatible entries prevent universal certification.'),
      'final_dots_unique':('Final-dot lane uniqueness','99.8752% overlap >70%; guard stopped at the first duplicate.'),
      'registry_snapshot_complete':('Complete universal registry comparison','All 2,729 downloads are indexed; 18 comparison quarantines remain. Inventory and universal comparability are different.'),
      'saved_bytes_valid':('Saved-byte format and range','13 shared checks pass: exact mirrored template grid, one float32 band, no NaN/Inf anywhere in the zero-filled file, values in [0,1].'),
      'current_best_reproduced':('Clean current-best OOF control','Upstream H38 is documented, not reproduced. Frozen full-catalogue peer masks are not clean hide-and-recover comparators.'),
      'paired_holdout_improvement':('Holdout improvement gate','SSP1 does not beat the documented upstream best; no valid paired win is claimed.'),
      'weekly_selector_approved':('Weekly-slot selector approval','Not requested or used. Current authenticated account capacity is unknown.')}
    html_rows=[]
    for key,value in c['decision']['gates'].items():
        title,note=labels[key];status='PASS' if value is True else ('UNKNOWN'if value is None else 'FAIL');kind='pass'if value is True else ('pending'if value is None else 'fail')
        html_rows.append(f'<div class="gate"><div class="gate-label">{e(title)}<span class="note">{e(note)}</span></div><strong class="{kind}">{status}</strong></div>')
    return ''.join(html_rows)


def lattice(c):
    l=c['lattice_feasibility']
    return f'''<div class="callout"><p class="eyebrow" style="color:#79551b">A measured contradiction, not a model excuse</p><h3>The overlap gate cannot pass at this budget.</h3><p>The registered spacing-five lattice leaves only <strong>{l['uncovered_pixels']:,}</strong> footprint cells farther than three pixels from its dots. Any <strong>{l['candidate_fixed_budget']:,}</strong>-dot map therefore has overlap at least <strong>{pct(l['minimum_possible_overlap_for_any_distinct_pixel_map_at_this_budget'])}</strong> — already above the 70% ceiling.</p><p class="subtle"><code>overlap ≥ max(0, 1 − uncovered_cells / candidate_dots)</code><br>No lattice exemption, boundary-gap targeting or decorative pixel jitter is applied. <a href="data/lattice_feasibility.json">Read the counting proof →</a></p></div>'''


def freshness(feed):
    return f'''<div class="card"><p class="eyebrow">Historical public leaderboard observation · not a submission receipt</p><h3>{feed['leading_public_value']:.4f} <span class="tag gold">Dated snapshot · not live</span></h3><p class="subtle">Observed {e(feed['last_success_utc'])} UTC. This is <strong>not</strong> a hash-linked score for our TIFF or any GEMSDOE file.</p><p class="tiny">Automatic DrivenData monitoring is disabled under its <a href="https://www.drivendata.org/termsofuse/">published terms</a>. The scheduled site build does not poll the leaderboard. Current account slots and organizer receipts remain unknown. <a href="data/leaderboard_snapshot.json">Snapshot state</a> · <a href="{e(feed['source'])}">Official leaderboard</a></p></div>'''


def hero(c,title,lead,kicker='Independent experiment · 26 October 2026'):
    return banner(c)+f'<section class="hero"><div><p class="eyebrow">{e(kicker)}</p><h1>{title}</h1><p class="lead">{lead}</p><div class="button-row"><a class="button light small" href="executive-summary.html#comparison">Compare all nine sites →</a><a class="button light small" href="submission-guide.html">How submission works →</a></div></div>'+download_panel(c)+'</section>'


def build_overview(c,peers,feed):
    body=hero(c,'Fault discovery.<br>Not wishful scoring.','A new geological hypothesis, a real downloadable GeoTIFF, and a decision backed by the actual bytes. This run produced a <strong>negative result</strong> — not a disguised promise of a higher leaderboard score.')
    body+=estimate(c)
    body+='''<section class="section"><div class="section-head"><div><p class="eyebrow">The finding that changes the strategy</p><h2>The leading peer files are mostly a family.</h2></div><p class="subtle">We compared the pixels and construction, not the model names or the number of websites.</p></div><div class="grid-3"><article class="card"><p class="eyebrow">01 · exact identity</p><h3>GEMSDOE25 = GEMSDOE30</h3><p class="subtle">Their best-claim D2.8 files have the same positive-pixel mask. Another upload of the same map adds no discovery evidence.</p></article><article class="card"><p class="eyebrow">02 · exact construction</p><h3>GEMSDOE32 is a collar cut</h3><p class="subtle">The reported 0.2778 map adds zero dots to D2.8. It removes 6,436 dots within two pixels of the public catalogue.</p></article><article class="card"><p class="eyebrow">03 · no causal overclaim</p><h3>Geometry can help; names cannot prove why.</h3><p class="subtle">Removing redundant mass can improve DTI. Without receipt-linked controlled runs and hidden truth, the exact score’s cause is unknown.</p></article></div></section>'''
    body+=lattice(c)
    body+='<section class="section grid-2"><article class="card"><p class="eyebrow">One new method · one frozen experiment</p><h2>SSP1: step versus smooth terrain.</h2><p class="subtle">A nine-point cross-normal profile tests an antisymmetric fault-like step after removing smooth slope and curvature. Independent gravity, LiDAR and radiometric controls help distinguish terrain mimics. No old prediction raster is an input.</p><p class="subtle">The result does not beat the documented upstream best. A new SHA is not a high-score validation gate.</p><a href="research.html">Read the hypothesis, equations and falsification →</a></article><article class="card"><p class="eyebrow">Machine decision · no inspector hand-off</p><h2>Why this file is rejected</h2>'+gates(c)+'</article></section>'
    body+=freshness(feed)
    body+='<section class="section"><div class="section-head"><div><p class="eyebrow">Full executive comparison</p><h2>Nine sites. One evidence standard.</h2></div><a href="executive-summary.html#comparison">View the complete download table →</a></div><p class="subtle">Every site has a pinned reference filename, historical-claim provenance, estimate availability and exact-mask / lane-duplicate result. None is silently selected for a new weekly slot.</p></section>'
    return page('Overview',body)


def build_executive(c,peers,feed):
    h=c['holdout_dti'];ci=h['ci95_cluster_bootstrap']
    body=hero(c,'What to download.<br>What not to submit.','<strong>No file is authorized for a new competition slot.</strong> The new SSP1 TIFF is format-valid and not an exact peer copy, but fails lane uniqueness and the improvement requirement. Historical peer files below are reference downloads, not new recommendations.','Executive summary · nine priority sites')
    body+=estimate(c)
    body+=f'''<section class="section"><h2>This run’s new file</h2><p class="tiny mobile-note">Swipe the table to see the full estimate and decision.</p><div class="table-shell"><table class="wide"><caption class="screen-reader">New SSP1 file and local validation estimate</caption><thead><tr><th>Download</th><th>Local estimate · HOLDOUT-DTI</th><th>Estimated leaderboard score</th><th>Uniqueness</th><th>Submission decision</th></tr></thead><tbody><tr><td><a href="downloads/{e(c['downloads']['tif'])}" download>↓ New GeoTIFF</a><span class="filename">{e(c['downloads']['tif'])}</span></td><td><strong>{f(h['pooled_dti'])}</strong><span class="note">95% CI [{f(ci[0])}, {f(ci[1])}]<br>{e(h['evaluator_version'])}<br>{h['n_withheld_positives']:,} positive events</span></td><td><strong>Unavailable</strong><span class="note">A local estimate is not a projection of hidden-test performance.</span></td><td>Exact comparable-mask: <strong>new</strong><br>Protocol lane: <strong class="fail">FAIL</strong><span class="note">99.8752% within 3 px of lattice; threshold 70%.</span></td><td><strong class="fail">DO NOT SUBMIT</strong><span class="note">Automated negative; not a request for human inspection.</span></td></tr></tbody></table></div></section>'''
    body+='''<section class="section" id="comparison"><div class="section-head"><div><p class="eyebrow">Best historical claim per requested site</p><h2>Download and uniqueness table</h2></div><p class="subtle">“Historical claim” is user-reported, NOT ORGANIZER-CONFIRMED. No file-linked submission receipt was available. The table does not turn those numbers into new estimates.</p></div><p class="tiny mobile-note">Swipe the table horizontally to see uniqueness and submission status.</p>'''+peer_table(peers)+'</section>'
    body+='''<div class="callout teal"><h3>The clearest answer about GEMSDOE32</h3><p>Its 0.2778 is the highest <strong>historical claim</strong> in the priority list. The bytes prove it is the 44,090-dot D2.8 parent minus 6,436 dots inside a two-pixel catalogue collar. That is a geometric refinement, not proof of a new geothermal mechanism. Resubmitting it is not a unique strategy.</p><p class="subtle">GEMSDOE28’s best listed rung30 variant has historical claim 0.2710. Its separate solo variant (historical claim 0.2708) is exactly reproduced by GEMSDOE31. The distinction is preserved, not conflated.</p></div>'''
    body+=lattice(c)
    body+='<section class="section grid-2"><article class="card"><h2>Why no precise leaderboard estimate?</h2><p class="subtle">The expert hidden faults are not known to be exchangeable with withheld public catalogue segments. Historical files are nested or identical, and full-catalogue exclusions contaminate frozen-mask hide-and-recover comparisons. A numeric projection would imply calibration we do not have.</p><p class="subtle">We publish local HOLDOUT-DTI with its population and CI, label historical claims as unverified, and leave hidden-score estimates unavailable.</p><a href="research.html#score-estimates">Read the identifiability argument →</a></article><article class="card"><h2>Next steps, in the right order</h2><ol class="subtle"><li>Resolve the literal registry/lattice contradiction centrally; do not waive it in this lane.</li><li>Restore a clean, fold-local current-best OOF comparator before another promotion claim.</li><li>Authenticate original data provenance; preserve geometry and quantization audits.</li><li>Only then preregister another single-lane test, within its experiment/time budget.</li></ol><p class="tiny">No weekly slot is spent here. <a href="submission-guide.html">Exact submission instructions →</a></p></article></section>'
    body+=freshness(feed)
    return page('Executive summary',body,'Executive summary')


def build_guide(c):
    v=c['validator_output']
    body=banner(c)+'<p class="eyebrow">Submission guide · an automated decision, not a manual inspection task</p><h1>Submit a TIFF.<br>Not this summary.</h1><p class="lead">DrivenData expects a single-band GeoTIFF, or a ZIP containing one GeoTIFF. A PDF, HTML executive summary, JSON run card or source archive is not a prediction file. <strong>The current SSP1 artifact is rejected: do not upload it.</strong></p>'
    body+='<section class="section grid-2">'+download_panel(c)+'<article class="card"><h2>Current authorization</h2>'+gates(c)+'</article></section>'
    body+=f'''<section class="section prose"><h2>How a future approved submission works</h2><ol class="steps"><li><h3>Require an explicit “OK TO SUBMIT” verdict.</h3><p>The exact file must pass saved-byte validation, complete uniqueness checks, leakage canaries and a clean same-evaluator holdout improvement gate. A separate selector must approve a real slot with current authenticated capacity. This run does not pass.</p></li><li><h3>Download the prediction TIFF or single-TIFF ZIP.</h3><p>Use the download attached to the approved run card, not an old peer copy and not this page. Verify its SHA-256 against the published receipt. The zero-filled version prevents NaN/sentinel issues in generic full-grid range checks; the NaN-outside twin follows the sample’s missing-data convention. Neither has an organizer acceptance receipt here.</p></li><li><h3>Open the official submission form.</h3><p>At <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/submissions/">DrivenData → New submission</a>, choose the approved <code>.tif</code> or its single-TIFF <code>.zip</code>. Use the exact short name and note from that run card. The name identifies an experiment; it does not make duplicate pixels unique.</p></li><li><h3>Preserve the organizer receipt.</h3><p>Link the submission ID, file hash, returned score and receipt before calling a result ORGANIZER-CONFIRMED. Public leaderboard observations alone do not establish a particular artifact’s score. Initial/final private-test selection remains separate.</p></li></ol><h2>The earlier “[0, 1]” error</h2><p>Without the rejected file’s bytes, the exact cause cannot be verified. Common failure modes include a finite nodata sentinel, a NaN passed into a generic numeric range check, an unbounded model output, or invalid values introduced during writing. This pipeline writes binary confidence values and re-opens the saved file rather than checking only an in-memory array.</p><div class="definition"><strong>Measured for this zero-filled TIFF:</strong> all {v['full_grid_finite_pixels']:,} cells are finite; minimum {v['in_footprint_min']:.1f}; maximum {v['in_footprint_max']:.1f}; no NaN or Inf anywhere; one float32 band; exact mirrored-template geometry. This is local validation, not a guarantee of portal acceptance or a high score.</div><h2>Unique name and short note</h2><p>These identify the rejected research artifact. They are not instructions to spend a slot.</p><div id="submission-name" class="text-box">{e(c['submission_name'])}</div><button class="button light small" data-copy="submission-name" type="button">Copy name</button><div id="submission-note" class="text-box">{e(c['submission_note'])}</div><div class="button-row"><button class="button light small" data-copy="submission-note" type="button">Copy note</button><a href="downloads/submission-note.txt" download>Download note</a><span class="tiny">{c['note_characters']} / 140 characters</span></div><p id="copy-status" class="tiny" aria-live="polite"></p><h2>Limits we do not hide</h2><ul><li>September 2026 rules section 3.4 describes up to three submissions per week, subject to the competition site. Current remaining account capacity is unknown because the submission page requires login.</li><li>This project does not ask for or store login secrets, automatically upload, choose a final entry or consume a slot.</li><li>All raster-format and scientific gating in this project is automatic. “Selector approval” is a separate protocol requirement, not a human-inspector workaround.</li><li>GitHub Pages is a static delivery surface. Python/Actions generate and validate the files; the browser does not invent new model predictions or scores.</li></ul><p><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/">Official metric and GeoTIFF format</a> · <a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">Official rules</a></p></section>'''
    return page('Submission guide',body,'Executive summary')


def build_research(c,hyp):
    table=[]
    for r in hyp['ranked_candidates']:
        table.append(f"<tr><td><strong>{r['rank']} · {r['id']}</strong><span class='note'>{e(r['status'])}</span></td><td>{e(r['hypothesis'])}<span class='note'>{e('; '.join(r['layers']))}</span></td><td>{e(r['signature'])}</td><td>{e(r['why_uncatalogued'])}<span class='note'>Mimic: {e(r['mimic'])}</span></td><td>{e(r['expected_DTI_improvement'])}<span class='note'>{e(r['implementation_cost'])}</span></td></tr>")
    h=c['holdout_dti'];lo,hi=h['ci95_cluster_bootstrap']
    body=banner(c)+'<p class="eyebrow">Preregistered science · one fixed lane</p><h1>Test the mechanism.<br>Keep the negative.</h1><p class="lead">Four candidate hypotheses were ranked before implementation. Only SSP1 was executed. No parent prediction raster was copied, blended or perturbed, and no alternative budget was tried after the duplicate stop.</p>'
    body+='''<section class="section prose"><h2>The target is fault presence, not confirmed vents.</h2><p>The official challenge asks for geological faults indicative of geothermal resources. A warm spring or conductive basin is neither a unique fault signature nor a productive-reservoir guarantee. New expert faults are the initial test labels; public catalogue faults are training evidence. That population difference is central, not a footnote.</p><p><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/">Official target and metric</a> · <a href="https://gdr.openei.org/submissions/1391">Official INGENIOUS resource catalogue</a></p></section><section class="section"><h2>The candidate shortlist</h2><p class="subtle">Ranking is a qualitative scientific prior, never a numeric projected score. All four use existing restored layers; none requires an unverified new external download. Cross-site novelty is tested, not assumed.</p><div class="table-shell"><table class="wide"><thead><tr><th>Priority / status</th><th>Hypothesis / layers</th><th>Physical signature</th><th>Missing faults / confounder</th><th>Expected improvement / cost</th></tr></thead><tbody>'''+''.join(table)+'</tbody></table></div></section>'
    body+='''<section class="section prose"><h2>SSP1: a step after a smooth-terrain null.</h2><p>Sample nine elevations along the local terrain-gradient normal at offsets −4 to +4 pixels. Project the observed profile and tanh step templates off the same smooth basis <code>[1,t,t²]</code>. The residualized template tests an odd-symmetric scarp, not simply a large slope. Two widths are fixed in advance: 0.7 and 1.4 pixels.</p><pre>Q = I − X X⁺,      X = [1,t,t²]
r = Q z,           s = Q tanh(t / w)
amplitude = (r · s) / (s · s)
R²_step = (r · s)² / [(r · r)(s · s)]</pre><p>This is a shape-fit feature, not a calibrated Bayes factor. Alluvial-fan terraces, paleoshorelines, roads and lithologic contacts can mimic it. Tangent persistence, gravity alignment and independently derived LiDAR/radiometric controls do not make those ambiguities disappear.</p><h3>Label hygiene</h3><p>The shared 35-channel cache is reused. The new 17-channel transform contains no fault-distance, coordinate or peer-prediction feature. Each whole hidden segment is removed from supervision. Models train outside the held quadrant plus a 15 px buffer, using only fold-visible labels and visible-only negative sampling. Visible test faults are masked pixel-exactly; withheld ones are not masked using the full catalogue.</p><h3>Feature-only leakage canaries</h3><p>All 17 supplied features were tested alone. Maximum either-direction AUC = <strong>0.564622</strong>, below 0.90. This is a LEAKAGE-CANARY diagnostic, not a model score. Passing it does not prove no leakage; provenance and split checks remain separate.</p>'''
    body+=f'''<h2>The measured result</h2><div class="definition"><strong>HOLDOUT-DTI {f(h['pooled_dti'])}</strong> · spatial 95% CI [{f(lo)}, {f(hi)}]<br>{e(h['evaluator_version'])} · {h['n_withheld_positives']:,} withheld positive-pixel events · 20,321 unique positive pixels across two draws.<br>Not a public/private leaderboard estimate.</div><p style="margin-top:18px">Upstream H38 reports HOLDOUT-DTI 0.116958 [0.100533, 0.132040] with the same evaluator and positive-event count. Its clean OOF outputs were not reproduced here. SSP1 does not beat its documented point estimate, and no valid paired improvement is claimed.</p><p>The 100 m cross-profile may describe broad erosional terrain better than subtle fault scarps. Encoded LiDAR max-aggregates do not preserve the original fine-resolution cross-section. These are hypotheses about failure, not post-hoc proven causes. The final overlap rule independently rejects the file, so iteration stopped.</p>'''
    body+='''<h2>Why 0.2778 is not evidence of a new physical mechanism</h2><p>The Champion is exactly D2.8 outside a full-catalogue two-pixel collar; no dots were added. For the official metric, <code>D = 0.2(TP + FP) + 0.8|G|</code>. Removing redundant dots while keeping kernel true-positive credit fixed lowers the denominator. That is a plausible geometric benefit, not proof of what happened on the hidden truth. A removed dot covering a new nearby fault could instead hurt.</p><p>Only exact catalogue pixels are officially masked. A 200 m collar is a heuristic, not an organizer exclusion rule. File names such as “PINN” do not establish independent physics. The receipt and hidden truth needed for a causal explanation are not available.</p><h2 id="score-estimates">Why there is no leaderboard point estimate</h2><p>A withheld public segment is not guaranteed to be exchangeable with a newly mapped expert fault. Many peer files are identical or nested, so they are not independent calibration examples. Stored full-catalogue masks also contaminate naive hide-and-recover comparisons. A regression from those claims would suggest calibration that has not been demonstrated.</p><p>Different hidden fault sets can agree with everything observed publicly yet assign very different DTI to this candidate. The honest automatic local estimate is HOLDOUT-DTI with its stated CI and population. A precise hidden-score projection is not identified by this evidence.</p><h2>Knowledge retained for future work</h2><p>Official GeoDAWN metadata documents overlapping surveys, differing flight specifications, acquisition blocks and terrain clearance; these can imitate structural evidence. GDR 1391 documents free shallow-temperature, paleogeothermal, geophysical and strain resources. Their physical interpretation and licensing must be checked separately from a download hash. The selected experiment needs no new source; unperformed external-data ideas are not presented as validated.</p><p><a href="data/scientific-review.md">Full scientific review (Markdown)</a> · <a href="data/hypotheses.json">Frozen preregistration</a> · <a href="data/next-session.md">Next-session plan</a> · <a href="sources.html">Verified source ledger</a></p></section>'''
    return page('Scientific research',body,'Research')


def build_sources(sources):
    body='<p class="eyebrow">Official facts, separate from model hypotheses</p><h1>Trace every claim.<br>Trust no label blindly.</h1><p class="lead">Public text was checked on 26 October 2026. Data binaries were restored from hash-pinned owner mirrors, not freshly authenticated against the organizer’s host. A checksum, a geological interpretation, a local estimate and a submission receipt answer different questions.</p><div class="callout"><h3>Evidence labels</h3><p><strong>HOLDOUT-DTI:</strong> local evaluator + positive count + spatial 95% CI. <strong>ORGANIZER-CONFIRMED:</strong> reserved for an actual submission-page receipt linked to the file hash; none is available for the peer claims. Public leaderboard observations and user-reported historical claims are explicitly separate, never promoted into receipts.</p></div><section class="card">'
    for s in sources['sources']:
        claims=''.join(f'<li>{e(x)}</li>'for x in s.get('claims_supported',[]))
        quotes=''.join(f'<blockquote>{e(q)}</blockquote>'for q in s.get('evidence',[]))
        body+=f'''<article class="source-entry" id="{e(s['id'])}"><p class="eyebrow">{e(s['id'])} · {e(s['kind'])}</p><h3>{e(s['publisher'])}</h3><p class="subtle">{e(s['status'])}{' · '+e(s['license'])if s.get('license')else ''}</p><a class="url" href="{e(s['url'])}">{e(s['url'])}</a>{quotes}<ul class="subtle">{claims}</ul>{'<p class="tiny"><strong>Limit:</strong> '+e(s['limit'])+'</p>'if s.get('limit')else ''}{'<p class="tiny">'+e(s['binary_access'])+'</p>'if s.get('binary_access')else ''}</article>'''
    body+='</section><p class="tiny" style="margin-top:20px"><a href="data/sources.json">Download structured source ledger</a> · Short excerpts include normalized mathematical transcriptions, not a full archive of each page.</p>'
    return page('Verified sources',body,'Sources')


def build_audit(c,irregs):
    v=c['validator_output'];checks=''.join(f'<li><span>{e(k.replace("_"," "))}</span><strong class="pass">PASS</strong></li>'for k,value in v['checks'].items()if value)
    body=banner(c)+'<p class="eyebrow">Saved bytes, explicit scope, reproducible decision</p><h1>Format is a gate.<br>Not a guarantee.</h1><p class="lead">The shared writer and evaluator are pinned byte-for-byte. The output is reopened, every cell is checked, and the decision fails closed. A new filename or a range-valid TIFF never overrides a failed scientific gate.</p>'
    body+='<section class="section grid-2"><article class="card"><h2>Shared format validator</h2><p class="subtle">13 / 13 checks pass on this zero-filled TIFF. Exact geometry is compared with the owner-mirrored sample, not claimed as freshly organizer-authenticated.</p><ul class="check-list">'+checks+'</ul></article><article class="card"><h2>Submission authorization</h2>'+gates(c)+'</article></section>'
    body+=f'''<section class="section grid-2"><article class="card"><h2>Exact file receipt</h2><span class="filename">{e(c['downloads']['tif'])}</span><p class="sha" style="margin-top:15px">{e(c['raster_sha256'])}</p><ul class="check-list"><li><span>Single band / dtype</span><strong>1 / float32</strong></li><li><span>Shape (rows × columns)</span><strong>3730 × 3292</strong></li><li><span>CRS</span><strong>EPSG:32611</strong></li><li><span>Transform</span><span class="mono">[100, 0, 243350,<br>0, −100, 4508550]</span></li><li><span>All-grid finite / range</span><strong>12,279,160 / [0,1]</strong></li></ul><p class="tiny" style="margin-top:15px">The NaN-outside twin has finite in-footprint values and only NaN outside. <a href="downloads/{e(c['downloads']['nan_twin'])}" download>Download twin (also rejected)</a>.</p></article><article class="card"><h2>Scope matters</h2><p class="subtle">All 92 listed repositories are pinned. All 2,729 non-data GeoTIFF entries were retrieved; 1,921 distinct file blobs were read. Surface correlations are full-footprint, not a random sample. Eighteen incompatible or malformed entries remain explicitly quarantined.</p><p class="subtle">Exact mask novelty is scoped to 2,711 comparable entries. Universal certification is incomplete. The final-dot guard stops at its first duplicate, the lattice; no maximum over untested final overlaps is claimed.</p><div class="mini-grid"><div><p class="tiny">Actual candidate dot density, aggregated for display. This is not ground truth or a confirmed fault/vent map.</p><a href="data/surface_guard.json">Original surface observation and quarantine list →</a></div><img class="density" src="assets/candidate-density.png" alt="Spatial density of this run’s predicted dots across the data footprint, not a truth map" width="290" height="340"></div></article></section>'''
    body+=lattice(c)
    body+='<section class="section"><h2>Irregularities — retained, not hidden</h2><div class="grid-2">'
    for r in irregs['items']:
        body+=f'<article class="card"><p class="eyebrow">{e(r["id"])} · {e(r["severity"])}</p><h3>{e(r["title"])}</h3><p class="subtle">{e(r["finding"])}</p><p class="tiny"><strong>Action:</strong> {e(r["action"])}</p></article>'
    body+='</div></section><section class="section card"><h2>Reproduce and inspect the record</h2><div class="button-row"><a href="data/run_card.json">JSON run card</a><a href="data/nine_site_audit.json">Nine-site pixel audit</a><a href="data/input_geometry_audit.json">Input geometry / sample discrepancy</a><a href="data/template_pins.json">Shared-tool hashes</a><a href="data/feature_canaries.json">Feature canaries</a><a href="data/surface_recheck.json">Independent full surface recheck</a><a href="data/browser_checks.json">Browser download checks</a><a href="downloads/SHA256SUMS.txt">Download checksums</a><a href="data/verification.json">Release verification</a><a href="data/review_passes.json">Three review passes</a><a href="data/requirements_matrix.json">Requirements matrix</a><a href="data/integration_audit.json">Parallel-safe integration</a></div><p class="tiny" style="margin-top:15px">The scientific pixels and original observation are preserved. <a href="data/review_amendments.json">Pass-2 reporting amendments</a> tighten incomplete-comparison gates and replace unmeasured legacy placeholders with null; they cannot turn the negative into an authorized file. See the repository for executable tests and retained OOF masks.</p></section>'
    return page('Automated audit',body,'Audit')


def build_peer(r,peers,c):
    h=r['frozen_raster_diagnostic'];lo,hi=h['ci95_cluster_bootstrap']
    pairrows=[]
    for p in peers['pairwise']:
        if r['site']not in(p['a'],p['b']):continue
        other=p['b']if p['a']==r['site']else p['a'];ov=p['a_within_3px_of_b']if p['a']==r['site']else p['b_within_3px_of_a']
        pairrows.append(f'<tr><td><a href="{other}.html">{other}</a></td><td>{"YES"if p["same_dot_mask"]else "NO"}</td><td>{p["spearman"]:.5f}</td><td>{pct(ov)}</td><td class="fail">{"DUPLICATE"if p["lane_duplicate"]else "No flag in this pair"}</td></tr>')
    body='<a class="back" href="../executive-summary.html#comparison">← Nine-site executive summary</a><p class="eyebrow">Pinned historical reference · not a new slot candidate</p><h1>'+r['site']+'</h1><p class="lead">'+e(r['method'])+'</p><div class="status-bar"><div><strong>DO NOT RESUBMIT AS A NEW UNIQUE ENTRY.</strong><p>Historical claim '+f"{r['historical_claim']['value']:.4f}"+' is USER-REPORTED / NOT ORGANIZER-CONFIRMED. No hash-linked organizer receipt is available. The estimated leaderboard result is unavailable.</p></div></div>'
    body+=f'<section class="section grid-2"><article class="card"><h2>Best listed historical-claim file</h2><a href="{e(r["download_url"])}">↓ Download pinned reference TIFF</a><span class="filename" style="margin-top:15px">{e(r["filename"])}</span><p class="sha">{e(r["sha256"])}</p><p class="subtle">{r["dots"]:,} dots · {r["on_catalogue"]:,} on exact catalogue pixels<br>Commit <code>{r["commit"][:12]}</code></p><p class="tiny">Highest in the supplied per-site historical claim list, not verified as the best possible or a new recommendation. Exact mask twins in the priority-best set: {e(", ".join(r["exact_mask_twins"])or "none")}. Lane-distinct from every priority peer: {"YES"if r["lane_distinct_from_all_other_priority_sites"]else "NO"}.</p></article><article class="card"><h2>Frozen-raster diagnostic — biased</h2><p class="subtle"><strong>HOLDOUT-DTI {f(h["pooled_dti"])}</strong><br>95% spatial CI [{f(lo)}, {f(hi)}]<br>{e(h["evaluator_version"])}<br>{h["n_withheld_positives"]:,} withheld positive events</p><div class="callout red"><p class="tiny">This is not a clean re-trained model estimate. A persisted raster may already have used or masked the full catalogue, including the later “hidden” positives. Do not interpret this diagnostic as its leaderboard score or use it to claim SSP1 beats the Champion.</p></div></article></section>'
    body+='<section class="section"><h2>Measured comparisons with the other priority-best files</h2><p class="subtle">The three-pixel fraction is directional: dots in this site near the other site. Pairwise duplicate flags also conservatively consider the reverse direction.</p><div class="table-shell"><table><thead><tr><th>Other site</th><th>Exact same mask?</th><th>Spearman</th><th>This site within 3 px</th><th>Lane result</th></tr></thead><tbody>'+''.join(pairrows)+'</tbody></table></div></section><p class="subtle"><a href="../data/nine_site_audit.json">Full independent audit</a> · <a href="../sources.html">Official facts and evidence limits</a></p>'
    return page(r['site']+' executive review',body,'Executive summary',prefix='../')


def preview(c):
    import numpy as np
    import rasterio
    from PIL import Image,ImageDraw
    with rasterio.open(DOCS/'downloads'/c['downloads']['tif'])as ds:a=ds.read(1)>0
    with np.load(DOCS/'data/validation_masks.npz')as z:foot=z['footprint']
    H,W=a.shape;stride=12;ph=(-H)%stride;pw=(-W)%stride
    density=np.pad(a,((0,ph),(0,pw))).reshape((H+ph)//stride,stride,(W+pw)//stride,stride).sum(axis=(1,3))
    valid=np.pad(foot,((0,ph),(0,pw))).reshape((H+ph)//stride,stride,(W+pw)//stride,stride).any(axis=(1,3))
    t=np.clip(density/8,0,1)
    light=np.array([224,235,228]);dark=np.array([20,87,79]);rgb=(light[None,None,:]*(1-t[:,:,None])+dark[None,None,:]*t[:,:,None]).astype(np.uint8)
    rgb[~valid]=[255,255,255]
    image=Image.fromarray(rgb).resize((290,329),Image.Resampling.NEAREST)
    canvas=Image.new('RGB',(290,340),'white');canvas.paste(image,(0,7));canvas.save(DOCS/'assets/candidate-density.png',optimize=True)


