    copies=['evidence/run_card.json','evidence/nine_site_audit.json','evidence/input_geometry_audit.json','evidence/lattice_feasibility.json','evidence/feature_canaries.json','evidence/surface_guard.json','registry/template_pins.json','registry/sources.json','registry/hypotheses.json','registry/leaderboard_snapshot.json','registry/irregularities.json','research/scientific-review.md','research/next-session.md']
