    pages={'index.html':build_overview(c,peers,feed),'executive-summary.html':build_executive(c,peers,feed),'submission-guide.html':build_guide(c),'research.html':build_research(c,hyp),'sources.html':build_sources(sources),'audit.html':build_audit(c,irregs)}
    for name,content in pages.items():(DOCS/name).write_text(content)
    for record in peers['sites']:(DOCS/'sites'/f"{record['site']}.html").write_text(build_peer(record,peers,c))
    (DOCS/'downloads/submission-note.txt').write_text('REJECTED RESEARCH ARTIFACT — DO NOT SUBMIT\n\nName: '+c['submission_name']+'\nNote: '+c['submission_note']+'\nSHA-256: '+c['raster_sha256']+'\n')
    sums=[]
    for p in sorted((DOCS/'downloads').glob('*')):
        if p.is_file()and p.name!='SHA256SUMS.txt':sums.append(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+p.name)
    (DOCS/'downloads/SHA256SUMS.txt').write_text('\n'.join(sums)+'\n')
    output=io.StringIO();writer=csv.writer(output,lineterminator="\n");writer.writerow(['site','filename','pinned_download_url','historical_claim_unverified','leaderboard_estimate','exact_mask_twins','protocol_lane_unique','ok_to_submit','sha256'])
    for r in peers['sites']:writer.writerow([r['site'],r['filename'],r['download_url'],r['historical_claim']['value'],'UNAVAILABLE',';'.join(r['exact_mask_twins']),r['lane_distinct_from_all_other_priority_sites'],False,r['sha256']])
    (DOCS/'data/nine_site_table.csv').write_text(output.getvalue())
    write_summary_md(c,peers,feed)
    print(f'Built {len(pages)+len(peers["sites"])} pages, executive Markdown, CSV and actual GeoTIFF download links.')

